def comps(A,val):
    H,W=A.shape; seen=np.zeros_like(A,bool); out=[]
    for r in range(H):
        for c in range(W):
            if A[r,c]==val and not seen[r,c]:
                st=[(r,c)]; seen[r,c]=True; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and A[ny,nx]==val and not seen[ny,nx]:
                            seen[ny,nx]=True; st.append((ny,nx))
                out.append(cells)
    return out
