def solve(T):
    cnt=Counter(T.flatten().tolist()); bg=cnt.most_common(1)[0][0]
    threes=set(map(tuple,np.argwhere(T==3).tolist()))
    twos=set(map(tuple,np.argwhere(T==2).tolist()))
    res=[row[:] for row in T.tolist()]
    cands=[]
    anchors3=list(threes); anchors2=list(twos)
