            seg_v=[(y,b[1]) for y in range(min(a[0],b[0]),max(a[0],b[0])+1)]
            path=set(seg_h)|set(seg_v)
            if len(path)>1 and clear(sorted(path)):
                cands.append((len(path),tuple(sorted(path))))
