    mc=sorted([c for c,jc in cc.items() if len(jc)==1])
    cols=[list(cc[c])[0] for c in mc]
    low,hi=min(cols),max(cols)
    out=[r[:] for r in A]
    for c in mc:
        j=list(cc[c])[0]
        t=max(i for i in range(H) if A[i][j]==c)
        for i in range(t+1,H):
            if out[i][j]!=bg: break
            out[i][j]=3
    # band on lowest row entirely background between markers (if any), else bottom
    band=[i for i in range(H) if all(A[i][j]==bg for j in range(low,hi+1))]
    b=band[-1] if band else H-1
    out[b]=[3 if (low<=j<=hi) else A[b][j] for j in range(W)]
    return out
print(f(D)==O)
